import { buildContainer } from './config/container';
import { loadEnvironment } from './config/environment';
import { createHttpApp } from './http/createHttpApp';

function main(): void {
  const environment = loadEnvironment();
  const container = buildContainer();
  const app = createHttpApp({ ...container, staffApiKey: environment.staffApiKey });

  const server = app.listen(environment.port, () => {
    console.log(`Order fulfilment API listening on port ${environment.port}`);
    if (environment.staffApiKeyGenerated) {
      console.warn(
        `STAFF_API_KEY is not set; generated a temporary staff key for this run: ${environment.staffApiKey}`,
      );
    }
  });
  server.on('error', (error) => {
    console.error('HTTP server failed:', error);
    process.exitCode = 1;
  });

  const shutdown = (): void => {
    server.close(() => process.exit(0));
  };
  process.once('SIGINT', shutdown);
  process.once('SIGTERM', shutdown);
}

main();

